// Type of the token subject.
// Ref: #/components/schemas/TokenType
type TokenType string

const (
	TokenTypeCustomer TokenType = "customer"
	TokenTypeAdmin    TokenType = "admin"
	TokenTypeService  TokenType = "service"
)

// AllValues returns all TokenType values.
func (TokenType) AllValues() []TokenType {
	return []TokenType{
		TokenTypeCustomer,
		TokenTypeAdmin,
		TokenTypeService,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s TokenType) MarshalText() ([]byte, error) {
	switch s {
	case TokenTypeCustomer:
		return []byte(s), nil
	case TokenTypeAdmin:
		return []byte(s), nil
	case TokenTypeService:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *TokenType) UnmarshalText(data []byte) error {
	switch TokenType(data) {
	case TokenTypeCustomer:
		*s = TokenTypeCustomer
		return nil
	case TokenTypeAdmin:
		*s = TokenTypeAdmin
		return nil
	case TokenTypeService:
		*s = TokenTypeService
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}
